1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
9	
10	const countDistinctMonsterTypes = (army: Card[]): number =>
11	  new Set(army.map((card) => card.monster)).size;
12	
13	const BASE_SPHINX_SCORE = 2;
14	
15	const SCORE_THRESHOLDS_RICHEST_FIRST: ReadonlyArray<{
16	  atLeastTypes: number;
17	  score: number;
18	}> = [
19	  { atLeastTypes: 6, score: 5 },
20	  { atLeastTypes: 5, score: 3 },
21	  { atLeastTypes: 4, score: 3 },
22	];
23	
24	export const scoreArmy = (army: Card[]): number => {
25	  const typeCount = countDistinctMonsterTypes(army);
26	  const richestThresholdMet = SCORE_THRESHOLDS_RICHEST_FIRST.find(
27	    ({ atLeastTypes }) => typeCount >= atLeastTypes,
28	  );
29	
30	  const scorePerSphinx = richestThresholdMet?.score ?? BASE_SPHINX_SCORE;
31	  const sphinxCount = army.filter(isSphinx).length;
32	  return scorePerSphinx * sphinxCount;
33	};
